27			gradio.shared.visible === true ? true : "hidden"
28		);
29	</script>
30	
31	<Block
32		elem_id={gradio.shared.elem_id}
33		elem_classes={gradio.shared.elem_classes}
34		visible={visibility}
35	>
36		{#if gradio.shared.loading_status}
37			<StatusTracker
38				autoscroll={gradio.shared.autoscroll}
39				i18n={gradio.i18n}
40				{...gradio.shared.loading_status}
41			/>
42		{/if}
43	
44		<Accordion
45			{label}
46			open={gradio.props.open}
47			onexpand={() => {
48				gradio.dispatch("expand");
49				gradio.dispatch("gradio_expand");
50			}}
51			oncollapse={() => gradio.dispatch("collapse")}
52		>
53			<BaseColumn>
54				<slot />
55			</BaseColumn>
56		</Accordion>
57	</Block>
